const effortLevels={basso:{depth:2,label:'Basso',description:'2 livelli · conseguenze immediate'},medio:{depth:3,label:'Medio',description:'3 livelli · effetti indiretti e un’alternativa'},alto:{depth:4,label:'Alto',description:'4 livelli · reazioni e controeffetti'},massimo:{depth:5,label:'Massimo',description:'5 livelli · conseguenze delle conseguenze'}};
function effortField(){return `<label class="field" for="effortSelect">Effort — profondità del ragionamento</label><select id="effortSelect">${Object.entries(effortLevels).map(([k,v])=>`<option value="${k}" ${effort===k?'selected':''}>${v.label} — ${v.description}</option>`).join('')}</select><p>Indica all’AI quanto spingersi lungo i nessi causali. Maggiore profondità significa più ipotesi da controllare, non maggiore certezza. Nella demo i rami sono predefiniti.</p>`}
let pan={x:0,y:0},inspectorOpen=false;
bindZoom=function(){$('#zoomIn').onclick=()=>{zoom=Math.min(1.5,zoom+.1);renderGraph()};$('#zoomOut').onclick=()=>{zoom=Math.max(.2,zoom-.1);renderGraph()};$('#zoomReset').onclick=fitGraph};
function graphData(){let n=nodes();const base=[{id:0,l:0,y:255},{id:1,l:1,y:150},{id:5,l:1,y:440},{id:2,l:2,y:150},{id:3,l:3,y:60},{id:4,l:3,y:285}];const extra=kind==='tariff'?[['SECONDO ORDINE','I concorrenti rispondono sui prezzi','Reazione competitiva'],['SECONDO ORDINE','Cambiano margini e mix di prodotto','Effetto economico'],['TERZO ORDINE','Il vantaggio di Amazon si riassorbe','Controeffetto'],['TERZO ORDINE','I consumatori cambiano ancora canale','Feedback sulla domanda']]:[['SECONDO ORDINE','Cresce la domanda di hardware dedicato','Capacità e investimenti'],['SECONDO ORDINE','I provider chiusi cambiano offerta','Servizi e distribuzione'],['TERZO ORDINE','Più efficienza riduce il costo di inference','Controeffetto sui volumi'],['TERZO ORDINE','Nuovi servizi ampliano la domanda AI','Feedback sul mercato']];if(kind==='custom')extra.forEach((a,i)=>a[1]=['Una reazione modifica l’effetto','Emergono costi indiretti','Un controeffetto limita la crescita','Il sistema trova un nuovo equilibrio'][i]);n=[...n,...extra];const all=[...base,{id:6,l:4,y:285},{id:7,l:4,y:60},{id:8,l:5,y:390},{id:9,l:5,y:115}].filter(x=>x.l<=effortLevels[effort].depth);return{items:all,n,edges:[[0,1],[0,5],[1,2],[2,3],[2,4],[4,6],[3,7],[6,8],[7,9]]}}
renderGraph=function(){if(!$('#graph'))return;const {items,n,edges}=graphData(),w=effortLevels[effort].depth*270+340;$('#graph').style.cssText=`width:${w}px;min-width:${w}px;height:680px;transform:translate(${pan.x}px,${pan.y}px) scale(${zoom});transform-origin:0 0;`;$('#graph').innerHTML=`<svg width="${w}" height="680" viewBox="0 0 ${w} 680"><defs><marker id="arrow" markerWidth="7" markerHeight="7" refX="6" refY="3.5" orient="auto"><path d="M0 0L6 3.5L0 7" fill="none" stroke="#777"/></marker></defs>${edges.filter(([a,b])=>items.some(x=>x.id===a)&&items.some(x=>x.id===b)).map(([a,b])=>{let from=items.find(x=>x.id===a),to=items.find(x=>x.id===b),x=from.l*270+255,y=from.y+45,tx=to.l*270+35,ty=to.y+45;return `<path d="M${x} ${y} H${x+25} V${ty} H${tx}" fill="none" stroke="#85857d" stroke-width="1" ${b===5?'stroke-dasharray="4 4"':''} marker-end="url(#arrow)"/>`}).join('')}</svg>${items.map(x=>`<button class="node ${x.id===0?'root':''} ${selected===x.id&&inspectorOpen?'selected':''}" style="left:${x.l*270+35}px;top:${x.y}px" data-node="${x.id}"><span class="node-type">${x.id===0?'TESI':x.id===5?'ALTERNATIVA':'LIVELLO '+x.l}<span class="node-index">[${String(x.id+1).padStart(2,'0')}]</span></span><strong>${esc(n[x.id][1])}</strong><span class="node-bottom">${friction!==30&&[2,3,4].includes(x.id)?(friction>60?'↓ nesso indebolito':'↔ scenario modificato'):esc(n[x.id][2])}</span></button>`).join('')}`;$$('[data-node]').forEach(b=>b.onclick=()=>{const i=+b.dataset.node;inspectorOpen=true;if(i<6){selectNode(i)}else{selected=i;$('#inspector').innerHTML=`<div class="inspector-header">LIVELLO ${items.find(x=>x.id===i).l} · CONSEGUENZA INDIRETTA</div><h3>${esc(n[i][1])}</h3><span class="status-tag">Ipotesi da verificare</span><div class="challenge-card"><small>DOMANDA CRITICA</small><p>Quali condizioni devono restare vere perché questo effetto si propaghi fino a qui?</p></div><p>Ogni passaggio aggiunge incertezza. Questo ramo è una possibilità da esplorare, non una previsione confermata.</p><div class="detail-label">SCENARIO CONTRARIO</div><p>La reazione dei concorrenti o un miglioramento di efficienza possono interrompere questa catena.</p>`;renderGraph()}openInspector()});$('#zoomLabel').textContent=Math.round(zoom*100)+'%';if($('#graphCount'))$('#graphCount').textContent=items.length+' nodi / '+effortLevels[effort].depth+' livelli';};
const previousInspector=renderInspector;renderInspector=function(){if(selected>5)selected=2;previousInspector();if(inspectorOpen)openInspector()};
function openInspector(){$('#inspector').classList.add('open');if(!$('#closeInspector')){const b=document.createElement('button');b.id='closeInspector';b.className='close-inspector';b.textContent='×';b.setAttribute('aria-label','Chiudi dettagli');b.onclick=()=>{inspectorOpen=false;$('#inspector').classList.remove('open');renderGraph()};$('#inspector').prepend(b)}}
const prevInit=initMap;initMap=function(){prevInit();$('.map-toolbar').innerHTML=`<div class="document-title"><span>TESI /</span> <button id="titleEdit">${esc(title)}</button></div><div class="graph-actions"><button id="effortButton">Effort: ${effortLevels[effort].label} ▾</button><button id="saveGraph">Salva</button></div>`;$('#titleEdit').onclick=()=>newDialog(true);$('#effortButton').onclick=effortDialog;$('#saveGraph').onclick=saveDialog;$('.canvas-caption').innerHTML='<span>MAPPA CAUSALE</span><span id="graphCount"></span>';$('.map-footer').innerHTML=`<div class="status-left"><span>DEMO</span> <span>Trascina il foglio · clicca un nodo</span></div><div class="zoom"><button id="scenario">Scenario</button><button id="zoomOut" aria-label="Riduci mappa">−</button><span id="zoomLabel">100%</span><button id="zoomIn" aria-label="Ingrandisci mappa">+</button><button id="zoomReset" aria-label="Centra mappa">Centra</button></div>`;$('#scenario').onclick=scenarioDialog;bindZoom();$('#zoomReset').onclick=fitGraph;const c=$('#canvas');let drag=null;c.onpointerdown=e=>{if(e.target.closest('button'))return;drag={x:e.clientX,y:e.clientY,px:pan.x,py:pan.y};c.setPointerCapture(e.pointerId);c.classList.add('dragging')};c.onpointermove=e=>{if(!drag)return;pan={x:drag.px+e.clientX-drag.x,y:drag.py+e.clientY-drag.y};$('#graph').style.transform=`translate(${pan.x}px,${pan.y}px) scale(${zoom})`};c.onpointerup=c.onpointercancel=()=>{drag=null;c.classList.remove('dragging')};renderGraph();};
function fitGraph(){if(!$('#canvas'))return;const w=$('#canvas').clientWidth,h=$('#canvas').clientHeight-90;zoom=Math.min(1,Math.max(.6,(w-50)/(effortLevels[effort].depth*270+340)));pan={x:20,y:Math.max(25,(h-580*zoom)/2)};renderGraph()}
function effortDialog(){modal(`${head('IMPOSTAZIONI DI ANALISI')}<h2>Quanto a fondo vuoi andare?</h2>${effortField()}<div class="modal-actions"><button class="button" data-close>Annulla</button><button class="button dark" id="applyEffort">Ricostruisci la mappa</button></div>`);$('#applyEffort').onclick=()=>{effort=$('#effortSelect').value;inspectorOpen=false;selected=2;$('#modal').close();showView('map');fitGraph();toast('Mappa ricostruita: '+effortLevels[effort].description)}}
const previousView=showView;showView=function(v){document.body.classList.toggle('map-mode',v==='map');closeMenu();inspectorOpen=false;previousView(v);if(v==='map')fitGraph()};
function closeMenu(){$('.sidebar').classList.remove('visible');$('#menuBackdrop').hidden=true;$('#menuToggle').setAttribute('aria-expanded','false')}
$('#menuToggle').onclick=()=>{const open=!$('.sidebar').classList.contains('visible');$('.sidebar').classList.toggle('visible',open);$('#menuBackdrop').hidden=!open;$('#menuToggle').setAttribute('aria-expanded',String(open))};$('#menuBackdrop').onclick=closeMenu;$('#newThesis').onclick=()=>{closeMenu();newDialog()};document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeMenu();if($('#inspector'))$('#inspector').classList.remove('open');inspectorOpen=false}});
showView('map');
// A first analysis always starts with an explicit depth choice.
modal(`${head('NESSO / NUOVA ANALISI')}<h2>Prima di tracciare i nessi.</h2><p class="initial-thesis">${esc(title)}</p>${effortField()}<div class="modal-actions"><button class="button" id="changeInitial">Cambia tesi</button><button class="button dark" id="startAnalysis">Avvia esplorazione →</button></div>`);$('#changeInitial').onclick=()=>{$('#modal').close();newDialog(true)};$('#startAnalysis').onclick=()=>{effort=$('#effortSelect').value;$('#modal').close();showView('map');fitGraph()};
